mapper.select:
SELECT 
FROM mt_im_message
WHERE app_id = #{appId}
  AND platform_msg_id = #{platformMsgId}
LIMIT 1

mapper.update:
UPDATE mt_im_message
SET delivery_status = #{deliveryStatus}, error_code = #{errorCode},
    error_summary = #{errorSummary}, update_time = #{updateTime}
WHERE id = #{id}

mapper.select:
SELECT 
FROM mt_im_message
WHERE conversation_id = #{conversationId}

    AND (event_time < #{cursorTime} OR (event_time = #{cursorTime} AND id < #{cursorId}))

ORDER BY event_time DESC, id DESC
LIMIT #{limit}
